/** Events */
export const events = {
	interactionClosed: makeEvent<InteractionClosed, InteractionClosed>("interaction-closed"),
	interactionRequest: makeEvent<InteractionRequest, InteractionRequest>("interaction-request"),
	quitBlocked: makeEvent<QuitBlocked, QuitBlocked>("quit-blocked"),
	sessionLost: makeEvent<SessionLost_Serialize, SessionLost_Deserialize>("session-lost"),
	transactionChanged: makeEvent<TransactionChanged_Serialize, TransactionChanged_Deserialize>("transaction-changed"),
};

/* Types */
/**  One MCP call, with its secrets already masked by the core. */
export type AuditEventItem = AuditEventItem_Serialize | AuditEventItem_Deserialize;

/**  One MCP call, with its secrets already masked by the core. */
export type AuditEventItem_Deserialize = {
	id: number,
	atMs: number,
	session?: string | null,
	client: string,
	connection: string,
	tool?: string | null,
	statement: string,
	status: AuditStatusItem,
	rows?: number | null,
	durationMs?: number | null,
	detail?: string | null,
};

/**  One MCP call, with its secrets already masked by the core. */
export type AuditEventItem_Serialize = {
	id: number,
	atMs: number,
	session: string | null,
	client: string,
	connection: string,
	tool: string | null,
	statement: string,
	status: AuditStatusItem,
	rows: number | null,
	durationMs: number | null,
	detail: string | null,
};

export type AuditFilterItem = AuditFilterItem_Serialize | AuditFilterItem_Deserialize;

export type AuditFilterItem_Deserialize = {
	search: string,
	tool?: string | null,
	status?: AuditStatusItem | null,
	session?: string | null,
};

export type AuditFilterItem_Serialize = {
	search: string,
	tool: string | null,
	status: AuditStatusItem | null,
	session: string | null,
};

export type AuditFormatItem = "csv" | "json";

export type AuditPageItem = AuditPageItem_Serialize | AuditPageItem_Deserialize;

export type AuditPageItem_Deserialize = {
	events: AuditEventItem_Deserialize[],
	/**  How many the filter keeps in all. */
	total: number,
};

export type AuditPageItem_Serialize = {
	events: AuditEventItem_Serialize[],
	/**  How many the filter keeps in all. */
	total: number,
};

export type AuditSessionItem = {
	session: string,
	client: string,
	startedMs: number,
	endedMs: number,
	calls: number,
	refused: number,
	failed: number,
};

export type AuditStatusItem = "ok" | "error" | "refused" | "cleared";

/**  An object bookmarked in the explorer (ADR-026). */
export type BookmarkItem = {
	connection: string,
	/**  The schema the object is in, or the schema itself (with an empty `name`). */
	schema: string,
	name: string,
	/**  `table`, `view`… for a relation, `function`, `sequence`… for another object, `schema`. */
	kind: string,
	/**  A function's arguments…; empty if nothing tells it apart from others of its name. */
	detail: string,
};

/**  A value typed in the grid for a result column (`None` is NULL). */
export type CellEditItem = CellEditItem_Serialize | CellEditItem_Deserialize;

/**  A value typed in the grid for a result column (`None` is NULL). */
export type CellEditItem_Deserialize = {
	column: number,
	value?: string | null,
};

/**  A value typed in the grid for a result column (`None` is NULL). */
export type CellEditItem_Serialize = {
	column: number,
	value: string | null,
};

/**
 *  Rows of a result by position, and the columns taken from each, in order (the grid leaves
 *  out the columns it hides).
 */
export type CellRange = {
	firstRow: number,
	rows: number,
	columns: number[],
};

/**  The clipboard form of a connection: no secrets, nothing that runs a program. */
export type ClipboardConnectionItem = {
	text: string,
	/**  Settings left out of the text, by the file's field names. */
	leftOut: string[],
};

export type ColumnDetails = ColumnDetails_Serialize | ColumnDetails_Deserialize;

export type ColumnDetails_Deserialize = {
	name: string,
	nativeType: string,
	nullable: boolean,
	default?: string | null,
	comment?: string | null,
};

export type ColumnDetails_Serialize = {
	name: string,
	nativeType: string,
	nullable: boolean,
	default: string | null,
	comment: string | null,
};

/**  One condition on a result column; all of them must hold. */
export type ColumnFilterItem = {
	column: number,
	op: FilterOpItem,
	value: string,
};

export type ColumnItem = {
	name: string,
	/**  Common logical type (`int`, `text`, `timestamptz`…). */
	logical: string,
	nativeType: string,
};

/**  A table column's statistics, counted by the server with read-only queries. */
export type ColumnStatsItem = ColumnStatsItem_Serialize | ColumnStatsItem_Deserialize;

/**  A table column's statistics, counted by the server with read-only queries. */
export type ColumnStatsItem_Deserialize = {
	/**  Rows the numbers describe (`sampleRows` when sampled). */
	rows: number | null,
	sampled: boolean,
	sampleRows: number | null,
	nulls: number | null,
	distinct?: number | null,
	distinctState: StatStateItem,
	min?: string | null,
	max?: string | null,
	rangeState: StatStateItem,
	top: TopValueItem_Deserialize[],
	topState: StatStateItem,
	/**  The statements that ran, every one a read. */
	statements: string[],
};

/**  A table column's statistics, counted by the server with read-only queries. */
export type ColumnStatsItem_Serialize = {
	/**  Rows the numbers describe (`sampleRows` when sampled). */
	rows: number | null,
	sampled: boolean,
	sampleRows: number | null,
	nulls: number | null,
	distinct: number | null,
	distinctState: StatStateItem,
	min: string | null,
	max: string | null,
	rangeState: StatStateItem,
	top: TopValueItem_Serialize[],
	topState: StatStateItem,
	/**  The statements that ran, every one a read. */
	statements: string[],
};

/**  How asking for a column's statistics ended. */
